/* Standard BST rotation: x drops down to become y's left child (rotate
 * left) or right child (rotate right); relinks x's displaced subtree,
 * y's parent, and the grandparent-or-root link. Doesn't touch colors. */
static void rb_rotate_left(rbtree_t *t, rbnode_t *x)
{
    rbnode_t *y = x->right;
    x->right = y->left;
    if (y->left != t->nil)
        y->left->parent = x;

    y->parent = x->parent;
    if (x->parent == t->nil)
        t->root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;

    y->left = x;
    x->parent = y;
}

static void rb_rotate_right(rbtree_t *t, rbnode_t *x)
{
    rbnode_t *y = x->left;
    x->left = y->right;
    if (y->right != t->nil)
        y->right->parent = x;

    y->parent = x->parent;
    if (x->parent == t->nil)
        t->root = y;
    else if (x == x->parent->right)
        x->parent->right = y;
    else
        x->parent->left = y;

    y->right = x;
    x->parent = y;
}
```

