661	    /* Case 9: a minimal LR zig-zag. "c" becomes the black root; "a" inserts
662	     * red as its left child with the fixup loop not running (parent is the
663	     * root); "b" then inserts red as "a"'s right child. "a" is red and is
664	     * "c"'s left child while "b" is "a"'s right child -- the mismatched
665	     * shape that forces a left-rotation at "a" followed by a right-rotation
666	     * at "c" (a genuine double rotation, not two independent single ones). */
667	    {
668	        static const char *keys[] = { "c", "a", "b" };
669	        /* sorted[] references keys[]'s own elements (not fresh literals) so
670	         * the value-pointer check below compares against the exact pointer
671	         * that was inserted, not a look-alike duplicate. */
672	        const char *sorted[] = { keys[1], keys[2], keys[0] }; /* a, b, c */
673	        size_t run_len = sizeof keys / sizeof keys[0];
674	        rbtree_t *t = rb_create(NULL);
675	        assert(t);
676	        for (size_t i = 0; i < run_len; i++) {
677	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
678	            assert(rb_size(t) == i + 1);
679	        }
680	
681	        assert(rb_validate(t) == 0);
682	
683	        collect_ctx_t collected = {0};
684	        rb_foreach(t, collect_cb, &collected);
685	        assert(collected.n == (int)run_len);
686	        for (int i = 0; i < collected.n; i++) {
687	            assert(strcmp(collected.keys[i], sorted[i]) == 0);
688	            assert(collected.values[i] == (void *)sorted[i]);
689	        }
690	
691	        for (size_t i = 0; i < run_len; i++)
692	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
693	
694	        rb_destroy(t);
695	        printf("ok - insert_rebalances_lr_zigzag\n");
696	    }
