698	    /* Case 10: a minimal RL zig-zag, the mirror of case 9. "a" becomes the
699	     * black root; "c" inserts red as its right child; "b" then inserts red
700	     * as "c"'s left child. "c" is "a"'s right child while "b" is "c"'s left
701	     * child, forcing a right-rotation at "c" then a left-rotation at "a". */
702	    {
703	        static const char *keys[] = { "a", "c", "b" };
704	        const char *sorted[] = { keys[0], keys[2], keys[1] }; /* a, b, c */
705	        size_t run_len = sizeof keys / sizeof keys[0];
706	        rbtree_t *t = rb_create(NULL);
707	        assert(t);
708	        for (size_t i = 0; i < run_len; i++) {
709	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
710	            assert(rb_size(t) == i + 1);
711	        }
712	
713	        assert(rb_validate(t) == 0);
714	
715	        collect_ctx_t collected = {0};
716	        rb_foreach(t, collect_cb, &collected);
717	        assert(collected.n == (int)run_len);
718	        for (int i = 0; i < collected.n; i++) {
719	            assert(strcmp(collected.keys[i], sorted[i]) == 0);
720	            assert(collected.values[i] == (void *)sorted[i]);
721	        }
